#include "taste_env.h"
#include <arpa/inet.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

#define PORT 5111
#define RECEIVER_PORT 5222
#define BUFFER_SIZE 8192

static const char IP_ADDRESS[] = "127.0.0.1";
static int sockfd;

static void *receiver_thread(void *arg)
{
	uint8_t buffer[BUFFER_SIZE];
	memset(buffer, 0x0, (size_t)BUFFER_SIZE);
	struct sockaddr_in client_addr;
	socklen_t addr_len = sizeof(client_addr);

	while (1) {
		int bytes_received = recvfrom(sockfd, buffer, BUFFER_SIZE - 1, 0,
				 (struct sockaddr *)&client_addr, &addr_len);
		if (bytes_received > 0) {
			buffer[bytes_received] = '\0';
		} else {
			perror("recvfrom failed\n");
			continue;
		}

		asn1SccCFDP_DATA pdu_data;
		memcpy(pdu_data.field_data.arr, buffer, bytes_received);
		pdu_data.field_data.nCount = bytes_received;

		taste_env_RI_received_pdu(&pdu_data);
	}

	return NULL;
}

