void taste_env_PI_read_file
      (const asn1SccCFDP_FILE_PATH *IN_file_path,
       const asn1SccCFDP_OFFSET *IN_offset,
       asn1SccCFDP_DATA *OUT_read_data,
       const asn1SccCFDP_SIZE *IN_size,
       asn1SccCFDP_BOOLEAN *OUT_result)

{
	FILE *file = fopen(IN_file_path->field_data, "rb");
	if (file == NULL) {
		printf("Error: Could not open file %s\n", IN_file_path->field_data);
		*OUT_result = false;
		return;
	}

	fseek(file, *IN_offset, SEEK_SET);
	if (fread(OUT_read_data->field_data.arr, sizeof(byte), *IN_size, file) != *IN_size) {
		printf("Error: Bad read\n");
		fclose(file);
		*OUT_result = false;
		return;
	}
	OUT_read_data->field_data.nCount = *IN_size;

	fclose(file);
	*OUT_result = true;
}

