void taste_env_PI_list_directory
	(const asn1SccCFDP_FILE_PATH * dir_path,
	asn1SccCFDP_DATA *listing_data,
	asn1SccCFDP_SIZE *size,
	asn1SccCFDP_BOOLEAN *OUT_result)
{
	DIR *dir = opendir(dir_path->field_data);
	if (!dir) {
		snprintf((char *)listing_data->field_data.arr, *size, "Error opening directory: %s\n", strerror(errno));
		*OUT_result = false;
		return;
	}

	struct dirent *entry;
	size_t offset = 0;

	while ((entry = readdir(dir)) != NULL) {
		if (strcmp(entry->d_name, ".") == 0 ||
		    strcmp(entry->d_name, "..") == 0)
			continue;

		int written = snprintf((char *)(listing_data->field_data.arr + offset), *size - offset, "%s\n", entry->d_name);
		if (written < 0 || (size_t)written >= *size - offset) {
			// Buffer full or error
			closedir(dir);
			*OUT_result = false;
			return;
		}
		offset += written;
	}
	listing_data->field_data.arr[offset] = '\0';
	closedir(dir);
	*OUT_result = true;
}

void taste_env_PI_send_pdu
    (const asn1SccCFDP_DATA *IN_pdu_data,
    asn1SccCFDP_BOOLEAN *OUT_result)
{
	struct sockaddr_in receiver_addr;
	memset(&receiver_addr, 0, sizeof(receiver_addr));
	receiver_addr.sin_family = AF_INET;
	receiver_addr.sin_addr.s_addr = inet_addr(IP_ADDRESS);
	receiver_addr.sin_port = htons(RECEIVER_PORT);

	int bytes_sent =
	    sendto(sockfd, IN_pdu_data->field_data.arr, IN_pdu_data->field_data.nCount, 0, (struct sockaddr *)&receiver_addr,
		   sizeof(receiver_addr));
	if (bytes_sent == -1) {
		int errsv = errno;
		printf("socket send error %d\n", errsv);
	}
    printf("socket bytes sent %d\n", bytes_sent);
    *OUT_result = true;
}

